import { useEffect, useState, useCallback } from "react";

export default function AdminOrders() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(false);

  // ---------- FETCH ORDERS ----------
  const fetchOrders = useCallback(async () => {
    try {
      const res = await fetch("http://127.0.0.1:8000/api/orders/", {
        cache: "no-store",
      });

      if (!res.ok) throw new Error("Failed to fetch orders");

      const data = await res.json();
      setOrders(data);
    } catch (err) {
      console.error("Fetch orders failed:", err);
    }
  }, []);

  // ---------- LIVE POLLING ----------
  useEffect(() => {
    fetchOrders(); // initial

    const interval = setInterval(fetchOrders, 2000);
    return () => clearInterval(interval);
  }, [fetchOrders]);

  // ---------- UPDATE STATUS ----------
  const updateStatus = async (order_id, status) => {
    try {
      setLoading(true);

      const res = await fetch(
        `http://127.0.0.1:8000/api/orders/${order_id}/status/`,
        {
          method: "PATCH",
          headers: {
            "Content-Type": "application/json",
            "Cache-Control": "no-cache",
          },
          body: JSON.stringify({ status }),
        }
      );

      if (!res.ok) throw new Error("Status update failed");

      const result = await res.json();

      // Optimistic UI update
      setOrders(prev =>
        prev.map(o =>
          o.order_id === order_id ? { ...o, status: result.status } : o
        )
      );

      // Re-sync from backend to avoid stale overwrite
      setTimeout(fetchOrders, 300);

    } catch (err) {
      console.error("Update status error:", err);
      alert("Failed to update order status");
    } finally {
      setLoading(false);
    }
  };

  // ---------- UI ----------
  return (
    <div>
      <h3>Live Orders</h3>

      {orders.length === 0 && <p>No orders yet</p>}

      {orders.map(o => (
        <div
          key={o.order_id}
          style={{
            border: "1px solid #ccc",
            padding: "10px",
            marginBottom: "10px",
          }}
        >
          <h4>Order #{o.order_id}</h4>
          <p>User: {o.user}</p>
          <p>Total: ₹{o.total}</p>

          <label>Status: </label>
          <select
            value={o.status}
            disabled={loading}
            onChange={e => updateStatus(o.order_id, e.target.value)}
          >
            <option value="Pending">Pending</option>
            <option value="Ready">Ready</option>
            <option value="Completed">Completed</option>
          </select>
        </div>
      ))}
    </div>
  );
}
